import test from 'node:test';import assert from 'node:assert/strict';import {isolateAtlas} from '../sprite-cutout.js';
test('neighbor feet above a head are removed without inverting the principal body',()=>{const a=new Uint8ClampedArray(20*20*4);const dot=(x,y)=>a[(y*20+x)*4+3]=255;for(let y=7;y<19;y++)for(let x=5;x<15;x++)dot(x,y);for(let x=6;x<10;x++)dot(x,1);const c=isolateAtlas(a,20,20,1,1);assert.equal(c.pixels[(1*20+7)*4+3],0);assert.equal(c.pixels[(18*20+7)*4+3],255);assert.equal(c.bounds[0].y,7);});
test('each atlas cell keeps its own connected actor',()=>{const a=new Uint8ClampedArray(20*10*4);for(let y=2;y<9;y++)for(const x of [3,4,13,14])a[(y*20+x)*4+3]=255;const c=isolateAtlas(a,20,10,2,1);assert.equal(c.bounds.length,2);assert.equal(c.bounds[0].x,3);assert.equal(c.bounds[1].x,13);assert.notEqual(c.pixels,a);assert.equal(a[(2*20+3)*4+3],255);});
